	/**
	 * Default Constructor
	 */
    public TwinTemplateService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TwinTemplateEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TwinTemplateRepository.class) );
		this.validator		= applicationContext.getBean(TwinTemplateValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		TwinTemplate
	 */
		public TwinTemplate createTwinTemplate( CreateTwinTemplateCommand command ) {

		TwinTemplate entity = new TwinTemplate();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTwinTemplateId( command.getTwinTemplateId() );
            entity.setName( command.getName() );
            entity.setSchemaUri( command.getSchemaUri() );
            entity.setVersion( command.getVersion() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of TwinTemplate {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTwinTemplateCommand
	 * @return		TwinTemplate
	 */
	public TwinTemplate updateTwinTemplate( UpdateTwinTemplateCommand command ) {

		TwinTemplate entity = new TwinTemplate();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTwinTemplateId( command.getTwinTemplateId() );
            entity.setName( command.getName() );
            entity.setSchemaUri( command.getSchemaUri() );
            entity.setVersion( command.getVersion() );
            entity.setDeviceModels( command.getDeviceModels() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of TwinTemplate {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTwinTemplateCommand
	 */
	public void delete( DeleteTwinTemplateCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTwinTemplateId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of TwinTemplate {0} ", id );

	}

	/**
	 * Method to retrieve the TwinTemplate via TwinTemplateFetchOneSummary
	 * @param 	summary TwinTemplateFetchOneSummary
	 * @return 	TwinTemplateFetchOneResponse
	 */
	public TwinTemplate getTwinTemplate( TwinTemplateFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TwinTemplateFetchOneSummary arg cannot be null" );

		TwinTemplate entity = null;
		UUID id = summary.getTwinTemplateId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a TwinTemplate using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all TwinTemplates
	 *
	 * @return 	List<TwinTemplate>
	 */
    public List<TwinTemplate> getAllTwinTemplate() {
		List<TwinTemplate> list = projector.findAll( new FindAllTwinTemplateQuery() );
		return list;
	}


	/**
	 * add DeviceModel to DeviceModels
	 * @param		command AssignDeviceModelsToTwinTemplateCommand
	 */
	public void addToDeviceModels( AssignDeviceModelsToTwinTemplateCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToDeviceModels(command.getTwinTemplateId(), command.getAddTo());
	}

	/**
	 * remove DeviceModel from DeviceModels
	 * @param		command RemoveDeviceModelsFromTwinTemplateCommand
	 */
	public void removeFromDeviceModels( RemoveDeviceModelsFromTwinTemplateCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromDeviceModels(command.getTwinTemplateId(), command.getRemoveFrom());
	}




